import{_ as a,c as t,o as r,ag as n}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Production-Ready Node.js Applications — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/module-10-production-ready-applications.md","filePath":"practice/node-js/module-10-production-ready-applications.md"}'),s={name:"practice/node-js/module-10-production-ready-applications.md"};function i(o,e,l,c,d,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="production-ready-node-js-applications-—-practice" tabindex="-1">Production-Ready Node.js Applications — practice <a class="header-anchor" href="#production-ready-node-js-applications-—-practice" aria-label="Permalink to “Production-Ready Node.js Applications — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These tasks were separated from the textbook; no completion is credited.</p><p><a href="./../../node-js/module-10-production-ready-applications.html">Textbook explanation</a> · <a href="./">Node.js practice map</a></p><h3 id="test-shutdown" tabindex="-1"><span class="hub-section-number">1 </span>Test shutdown <a class="header-anchor" href="#test-shutdown" aria-label="Permalink to “1 Test shutdown”">​</a></h3><p>An automated integration test can:</p><ol><li>Start the application on an ephemeral port.</li><li>Begin a controlled slow request.</li><li>trigger the shutdown function directly rather than signaling the test runner;</li><li>verify readiness becomes <code>503</code>;</li><li>verify the in-flight request completes;</li><li>verify new connections are rejected;</li><li>verify pools and workers close;</li><li>verify the deadline handles a deliberately stuck resource.</li></ol><hr><h2 id="graduated-practice-logging-and-lifecycle" tabindex="-1"><span class="hub-section-number">2 </span>Graduated practice: logging and lifecycle <a class="header-anchor" href="#graduated-practice-logging-and-lifecycle" aria-label="Permalink to “2 Graduated practice: logging and lifecycle”">​</a></h2><h3 id="_1-worked-example" tabindex="-1"><span class="hub-section-number">2.1 </span>Worked example <a class="header-anchor" href="#_1-worked-example" aria-label="Permalink to “2.1 Worked example”">​</a></h3><p>Run the retained application using its README, then exercise the lifecycle contract. Observe one request ID, two different health checks, and a signal-triggered shutdown. Follow <code>server.ts</code> → <code>createShutdown</code> → <code>db.close</code>; identify which function owns each resource.</p><h3 id="_2-guided-failure" tabindex="-1"><span class="hub-section-number">2.2 </span>Guided failure <a class="header-anchor" href="#_2-guided-failure" aria-label="Permalink to “2.2 Guided failure”">​</a></h3><p>Start with an unreachable database port. Hint: metadata discovery does not establish connectivity. <strong>Success:</strong> HTTP never listens, startup reports only a stable diagnostic code, and the command terminates unsuccessfully. Then restore the database and repeat a successful start.</p><h3 id="_3-independent-task" tabindex="-1"><span class="hub-section-number">2.3 </span>Independent task <a class="header-anchor" href="#_3-independent-task" aria-label="Permalink to “2.3 Independent task”">​</a></h3><p>Add a bounded background job with explicit <code>stopIntake</code> and <code>drain</code> ownership. <strong>Success:</strong> SIGTERM prevents new jobs, lets an active job finish, and closes its database only after the job releases it. A stuck job reaches the process deadline. Use a child process to test forced termination.</p><h3 id="_4-optional-depth-structured-diagnostics" tabindex="-1"><span class="hub-section-number">2.4 </span>Optional depth: structured diagnostics <a class="header-anchor" href="#_4-optional-depth-structured-diagnostics" aria-label="Permalink to “2.4 Optional depth: structured diagnostics”">​</a></h3><p>Use the primary Node 24/Express 5 stack and a locked Winston 3 version. Route metadata must be developer-defined templates; no req.path/originalUrl fallback on matched, unmatched or aborted requests. A router mounted under a prefix may need explicit static route IDs to distinguish operations. Never derive a log/metric route label by partially redacting a raw URL. Keep request IDs bounded and accept an upstream value only under an explicit trusted-gateway policy; they are correlation metadata, never authorization.</p><p><strong>Acceptance:</strong> capture actual Winston JSON output. A nested raw Error demonstrates missing stack with the errors formatter alone; the explicit owned projection preserves bounded stack/cause codes. Put token/password/SQL sentinels into an unknown error message, enumerable fields, cause object and raw URL; none may appear in emitted records. Mutating an owned Error&#39;s message/stack after construction must not alter its recorded safe diagnostic. More than three causes truncate predictably.</p><p>Unknown exceptions remain observable as a stable category rather than silently disappearing. Matched routes emit a static template; unmatched/aborted routes use a fixed label. Run overlapping asynchronous request contexts and prove each completion/inner event retains its own ID. Retain evidence of the actual sink format, without recording real secrets.</p><p>Keep a short record of the emitted JSON and sentinel checks. Review retention/access controls when choosing a hosted log sink.</p><p>References checked 2026-10-21: <a href="https://github.com/winstonjs/logform#errors" target="_blank" rel="noreferrer">logform errors format contract</a>, <a href="https://github.com/winstonjs/winston" target="_blank" rel="noreferrer">Winston formats/transports</a>, <a href="https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP logging and sensitive data</a>, <a href="https://nodejs.org/download/release/v24.18.0/docs/api/async_context.html" target="_blank" rel="noreferrer">Node 24 AsyncLocalStorage</a>.</p><h3 id="_5-optional-depth-lifecycle-failure-matrix" tabindex="-1"><span class="hub-section-number">2.5 </span>Optional depth: lifecycle failure matrix <a class="header-anchor" href="#_5-optional-depth-lifecycle-failure-matrix" aria-label="Permalink to “2.5 Optional depth: lifecycle failure matrix”">​</a></h3><p><strong>Acceptance:</strong> start on an ephemeral port, hold a slow request/job, initiate shutdown twice and prove both calls share one promise. Intake stops immediately and readiness becomes false; active work finishes before database close; new connections are rejected. Force server-close/job/database failures separately and together: every eligible cleanup runs, failure exit status is nonzero and completed is absent. A job that cannot release its database ownership keeps drain pending until the final child-process deadline. Test deadline termination and uncaught startup rejection in disposable child processes, not the parent test runner.</p><p>Bind a second server to an occupied address and verify the async startup rejection closes its handed-over database. For readiness, issue concurrent calls to a deliberately never-settling ping: each reply returns false within budget and underlying call count stays one across subsequent probes. Then use a real driver-backed slow query with configured statement/acquisition limits; prove the query actually ends and later probes can recover. A response-only Promise.race test does not demonstrate database cancellation.</p><p>Test shutdown beginning during a successful ping to prevent a late 200 readiness response. Record the observed deadlines and exit statuses; do not infer driver cancellation from the HTTP response alone.</p><p>References checked 2026-10-21: <a href="https://nodejs.org/download/release/v24.18.0/docs/api/http.html" target="_blank" rel="noreferrer">Node 24 HTTP server lifecycle</a>, <a href="https://nodejs.org/download/release/v24.18.0/docs/api/net.html" target="_blank" rel="noreferrer">Node 24 net listen/error events</a>, <a href="https://node-postgres.com/apis/client" target="_blank" rel="noreferrer">pg client timeout configuration</a>, <a href="https://www.postgresql.org/docs/16/runtime-config-client.html#GUC-STATEMENT-TIMEOUT" target="_blank" rel="noreferrer">PostgreSQL statement timeout</a>, <a href="https://mikro-orm.io/docs/configuration#driver-options" target="_blank" rel="noreferrer">MikroORM 7 driver options</a>.</p><hr><h2 id="_15-final-review-checklist" tabindex="-1"><span class="hub-section-number">3 </span>Final review checklist <a class="header-anchor" href="#_15-final-review-checklist" aria-label="Permalink to “3 Final review checklist”">​</a></h2><h3 id="architecture-and-deployment" tabindex="-1"><span class="hub-section-number">3.1 </span>Architecture and deployment <a class="header-anchor" href="#architecture-and-deployment" aria-label="Permalink to “3.1 Architecture and deployment”">​</a></h3><ul><li>[ ] Explain VMs, multiple instances, containers/orchestrators, and serverless trade-offs.</li><li>[ ] Keep correctness independent of one process&#39;s memory or local disk.</li><li>[ ] Build once and configure the same artifact per environment.</li><li>[ ] Run migrations as controlled one-off release/admin work.</li><li>[ ] Rely on an external supervisor for restart and replacement.</li></ul><h3 id="configuration" tabindex="-1"><span class="hub-section-number">3.2 </span>Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “3.2 Configuration”">​</a></h3><ul><li>[ ] Parse and validate all environment values before listening.</li><li>[ ] Never provide unsafe defaults for secrets or trust decisions.</li><li>[ ] Export a typed configuration object instead of spreading <code>process.env</code> reads.</li><li>[ ] Keep production secrets out of source, images, <code>.env</code> files, logs, and error output.</li><li>[ ] Understand Node&#39;s <code>--env-file</code> and the local-development role of dotenv-style files.</li></ul><h3 id="logging-and-observability" tabindex="-1"><span class="hub-section-number">3.3 </span>Logging and observability <a class="header-anchor" href="#logging-and-observability" aria-label="Permalink to “3.3 Logging and observability”">​</a></h3><ul><li>[ ] Emit structured events with deliberate severity levels.</li><li>[ ] Preserve error stacks/causes and avoid duplicate logging.</li><li>[ ] Redact credentials and unnecessary personal data.</li><li>[ ] Propagate validated correlation context with <code>AsyncLocalStorage</code> or tracing.</li><li>[ ] Distinguish operational logs, audit events, metrics, and traces.</li><li>[ ] Avoid high-cardinality metric labels.</li></ul><h3 id="health-and-lifecycle" tabindex="-1"><span class="hub-section-number">3.4 </span>Health and lifecycle <a class="header-anchor" href="#health-and-lifecycle" aria-label="Permalink to “3.4 Health and lifecycle”">​</a></h3><ul><li>[ ] Distinguish startup, liveness, and readiness consequences.</li><li>[ ] Keep liveness shallow and readiness bounded by timeouts.</li><li>[ ] Mark the instance unready before draining.</li><li>[ ] Stop new work, complete bounded in-flight work, and close owned resources.</li><li>[ ] Handle WebSockets, workers, consumers, timers, pools, and telemetry explicitly.</li><li>[ ] Keep shutdown shorter than the platform&#39;s forced-termination deadline.</li></ul><h3 id="errors-and-security" tabindex="-1"><span class="hub-section-number">3.5 </span>Errors and security <a class="header-anchor" href="#errors-and-security" aria-label="Permalink to “3.5 Errors and security”">​</a></h3><ul><li>[ ] Use a final Express error handler and respect <code>headersSent</code>.</li><li>[ ] Return stable public errors without production stack traces.</li><li>[ ] Treat uncaught exceptions and unhandled rejections as fatal defects.</li><li>[ ] Use TLS and configure proxy trust precisely.</li><li>[ ] Apply Helmet as a reviewed baseline, not a complete security solution.</li><li>[ ] Understand that CORS is a browser read policy, not authorization.</li><li>[ ] Configure rate limits for the actual multi-instance deployment and threat model.</li><li>[ ] Bound body size, query cost, concurrency, queues, pools, and dependency duration.</li></ul>',37)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
